  assert.equal(sourceBeforeCutoverHold224(file,raw),pin.beforeText);
  assert.equal(sourceBeforeCutoverHold224(file,raw+'\nUNKNOWN_BYTE'),raw+'\nUNKNOWN_BYTE');
 }
});
